import React from "react";

const Header = ({ username, setIsMenuOpen }) => {
  const handleUsernameClick = () => {
    setIsMenuOpen((prev) => !prev); // Alterna o menu de logout
  };

  return (
    <header className="flex justify-between items-center p-4 bg-yellow-500">
      <div className="text-white font-bold">Logo</div>
      <div>
        <button onClick={handleUsernameClick} className="text-white">
          Olá, {username}
        </button>
      </div>
    </header>
  );
};

export default Header;
